.landing-page{
  section{
    .title{
      text-align: center;
      position: relative;
      margin-bottom: 35px;
      a{
        color: variables.$theme-body-font-color;
        font-size: 30px;
        font-weight: 700;
        &::before{
          width: 28px;
          height: 5px;
          display: block;
          content: "";
          position: absolute;
          bottom: -2px;
          z-index: 1;
          left: 50%;
          margin-left: -14px;
          background-color: variables.$primary-color;
        }
        &::after{
          width: 100px;
          height: 1px;
          display: block;
          content: "";
          position: relative;
          margin-top: 10px;
          left: 50%;
          margin-left: -50px;
          background-color: variables.$light-primary;
        }
      }
    }
  }
  .section-py-space {
    padding-top: 70px;
    padding-bottom: 70px;
    @media (max-width: 1199px) {
      padding-top: 60px;
      padding-bottom: 60px;
    }
    @media (max-width: 991px) {
      padding-top: 50px;
      padding-bottom: 50px;
    }
    @media (max-width: 767px) {
      padding-top: 40px;
      padding-bottom: 40px;
    }
  }
  .section-pt-space {
    padding-top: 70px;
  }
  .section-pb-space {
    padding-bottom: 70px;
  }
  .landing-header{
    padding: 15px 120px;
    transition: all 0.5s ease-in-out;
    top: 0;
    left: 0;
    width: 100%;
    z-index: 10;
    position: fixed;
    background-color: variables.$transparent-color;
    ul{
      &.landing-menu{
        li{
          &.nav-item{
            position: relative;
            left: 0;
            &.menu-back{
              text-align: right;
              padding: 22px 20px;
              border-bottom: 1px solid variables.$table-border-color;
              text-transform: uppercase;
              font-weight: 700;
              font-size: 16px;
              display: none;
              cursor: pointer;
              margin-bottom: 15px;
              i{
                font-size: 16px;
                margin-left: 10px;
              }
            }
            a{
              &.nav-link{
                font-size: 16px;
                font-weight: 600;
                color: variables.$white;
                padding: 10px 15px;
                letter-spacing: 0;
                &:hover,
                &:active{
                  color: var(--theme-default);
                }
              }
            }
            &:active,
              &:hover {
                color: variables.$primary-color;
                transition: all 0.3s ease-in-out;
                &::after {
                  width: 60%;
                }
              }
              &::after {
                content: "";
                position: absolute;
                width: 0;
                height: 3px;
                bottom: -1px;
                left: 14px;
                background-color: var(--theme-default);
                opacity: 0.3;
                border-radius: 50px;
                transition: all 0.3s ease-in-out;
              }
          }
        }
      }
    }
    .buy-block{
      display: flex;
      align-items: center;
      .toggle-menu{
        margin-left: 20px;
        display: none;
        cursor: pointer;
        i{
          font-size: 24px;
          color: variables.$white;
        }
      }
    }
    &.sticky{
      background-color: variables.$theme-body-font-color;
      transition: all 0.5s ease-in-out;
    }
  }
  .btn-landing{
    border-radius: 10px;
    color: variables.$white;
    background-color: var(--theme-default);
    opacity: 0.9;
    padding: 12px 30px;
    line-height: 1;
    font-weight: 600;
    display: flex;
    align-items: center;
    @media (max-width: 320px) {
      padding: 8px 20px;
    }
  }
  .landing-home{
    background-image: url(../images/landing/Bg.png);
    background-position: center;
    background-size: cover;
    background-repeat: no-repeat;
    overflow: hidden;
    position: relative;
    .fluid-space{
      padding: 0 120px;
    }
    .banner-inner{
      .tech-icon{
        position: absolute;
        &.one{
          left: 6%;
          top: 212px;
          @media (max-width: 320px) {
            top: 100px;
          }
          animation-delay: 1s;
          img{
            animation: upDown 4s linear infinite;
          }
        }
        &.two{
          left: 8%;
          top: 450px;
          animation-delay: 1s;
          @media (max-width: 576px) {
            top: 370px;
          }
          @media (max-width: 320px) {
            top: 295px;
          }
          img{
            animation: loading-spinner 4s linear infinite;
          }
        }
        &.three{
          left: 24%;
          top: 445px;
          animation-delay: 1s;
          img{
            animation: loading-spinner 4s linear infinite;
          }
          @media (max-width: 1841px) {
            top: 470px;
          }
          @media (max-width: 1689px) {
            top: 477px;
          }
          @media (max-width: 1540px) {
            top: 480px;
          }
          @media (max-width: 1468px) {
            top: 487px;
          }
          @media (max-width: 1200px) {
            top: 410px;
            left: 286px;
          }
          @media (max-width: 1125px) {
            top: 415px;
            left: 265px;
          }
          @media (max-width: 1058px) {
            top: 444px;
            left: 249px;
          }
          @media (max-width: 992px) {
            left: 238px;
            top: 442px;
          }
          @media (max-width: 875px) {
            left: 205px;
          }
          @media (max-width: 576px) {
            left: 198px;
            top: 480px;
          }
          @media (max-width: 480px) {
            left: 162px;
            top: 400px;
          }
          @media (max-width: 320px) {
            left: 106px;
            top: 465px;
          }
        }
        &.four{
          left: 75%;
          top: 291px;
          animation-delay: 1s;
          img{
            animation: upDown 4s linear infinite;
          }
        }
        &.five{
          left: 86%;
          top: 410px;
          animation-delay: 1s;
          img{
            animation: loading-spinner 4s linear infinite;
          }
        }
        &.six{
          left: 98%;
          top: 200px;
          animation-delay: 1s;
          img{
            animation: animateWave 2s ease-in-out infinite;
          }
        }
      }
    }
    .dashboard-img{
      position: relative;
      top: 125px;
      animation: move2 1.2s infinite alternate;
      img{
        width: 100%;
      }
    }
    .landing-flex{
      padding-top: 96px;
    .content-home{
      text-align: center;
      padding-top: 96px;
      @media (max-width: 320px) {
        padding-top: 0;
      }
      .title-content{
        color: variables.$white;
        position: relative;
        text-transform: uppercase;
        margin-bottom: 50px;
        h1{
          color: variables.$white;
          font-size: calc(24px + (45 - 24) * ((100vw - 320px) / (1920 - 320)));
          font-weight: 800;
          margin-bottom: 9px;
          span{
            color: variables.$primary-color;
          }
          @media (max-width: 576px) {
            width: 95%;
            margin: auto;
          }
        }
        p{
          color: variables.$theme-body-sub-title-color;
          font-size: 16px;
          text-transform: capitalize;
          width: 40%;
          margin: auto;
          @media (max-width: 1200px) {
            width: 70%;
          }
          @media (max-width: 768px) {
            width: 85%;
          }
          @media (max-width: 576px) {
            width: 90%;
          }
        }
      }
      .main-buttons{
        display: flex;
        gap: 15px;
        align-items: center;
        margin-top: 30px;
        justify-content: center;
        @media (max-width: 320px) {
          gap: 7px;
        }
          .btn-primary,
          .btn-secondary{
            padding: 8px 18px;
            font-size: 16px;
            transition: all .5s ease;
            border-radius: 10px;
            @media (max-width: 320px) {
              font-size: 14px;
            }
          }
        }
        .hero-image{
          .slick-slide{
            transform: scale(1);
            transition: transform 0.3s ease;
            opacity: 0.6;
            img{
              margin-top: 50px;
              border-top-left-radius: 10px;
              border-top-right-radius: 10px;
              @media (max-width: 1200px) {
                margin-top: 30px;
              }
            }
          }
          .slick-center{
            transform: scale(1.5);
            opacity: 1;
            z-index: 2;
            position: relative;
          }
          .slick-slide{
            transition: transform 0.5s ease, opacity 0.5s ease;
          }
          .slick-list{
            .slick-track{
              padding-top: 80px;
              @media (max-width: 1243px) {
                padding-top: 45px;
              }
            }
          }
          .slick-current{
            + .slick-active{
                transform: scale(1.5);
                opacity: 1;
                z-index: 2;
                position: relative;
            }
          }
        }
      }
    }
  }
