  // layout section
  .layout-section {
    background-color: variables.$white;
    .layout-list {
      display: flex;
      justify-content: center;
      margin-bottom: 35px;
      border: none;
      @media (max-width: 480px) {
        margin-bottom: 12px;
      }
      .nav-item {
        .nav-link {
          padding: 14px 25px;
          background-color: rgba(variables.$primary-color, 0.1);
          border-radius: 10px;
          font-weight: 600;
          @media (max-width: 991px) {
            padding: 8px 14px;
          }
          &.active {
            background-color: variables.$primary-color;
            color: variables.$white;
          }
        }
        + .nav-item {
          margin-left: 18px;
        }
      }
      li{
        @media (max-width: 480px) {
          margin-bottom: 10px;
        }
      }
    }
    .layout-links {
      .row {
        margin-bottom: -30px;
        > div {
          margin-bottom: 30px;
        }
      }
      .layout-box {
        background-color: variables.$white;
        padding: 15px;
        border-radius: 10px;
        box-shadow: 0 0 20px rgba(8, 21, 66, 0.2);
        ul{
          margin-top: 18px;
          align-items: center;
          justify-content: center;
          flex-wrap: wrap;
          img{
            border-radius: 0;
          }
          li{
            border: 1px solid rgba(variables.$primary-color, 0.5);
            border-radius: 10px;
            transition: all 0.4s;
            &:hover {
              background-color: variables.$primary-color;
              a {
                color: variables.$white;
              }
            }
            a{
              padding: 9px;
              display: flex;
              font-weight: 600;
              align-items: center;
            }
            + li{
              margin-left: 12px;
            }
            &:nth-last-child(-n+2){
              margin-top: 10px;
            }
          }
        }
        img {
          transition: all 0.5s ease;
          border-radius: 10px;
        }
        &:hover {
          img {
            transform: scale(1.02);
          }
        }
      }
      .nav-link {
        border-radius: 10px;
        padding: 15px 30px;
        align-items: center;
        background-color: rgba(92, 97, 242, 0.8);
        position: relative;
      }
    }
  }

  // framework section
  .framework-section{
    background-color: rgb(129 131 133 / 6%);
    .demo-img1{
      margin: 0;
    }
    .frameworks-list{
      text-align: center;
      display: flex;
      justify-content: center;
      gap: 50px;
      flex-wrap: wrap;
      li{
        .box{
          display: flex;
          align-items: center;
          width: 125px;
          height: 108px;
          gap: 14px;
          background: variables.$bg-light-primary;
          border-radius: 5px;
          border-radius: 47% 53% 43% 57% / 36% 45% 55% 64%;
          position: relative;
          cursor: pointer;
          transition: all 0.2s ease;
          &:hover{
            animation: morph 8s ease-in-out infinite;
          }
          @media (max-width: 1199px) {
            width: 100px;
            height: 90px;
          }
          @media (max-width: 767px) {
            width: 85px;
            height: 85px;
          }
        }
        div{
          height: 40px;
          width: 40px;
          display: flex;
          align-items: center;
          justify-content: center;
          border-radius: 6px;
          img{
            height: calc(30px + (45 - 30) * ((100vw - 320px) / (1920 - 320)));
          }
        }
        h4{
          color: variables.$theme-body-font-color;
          margin-top: 10px;
        }
      }
    }
  }

  .application-section{
    .app-box{
      padding: 12px;
      .app-wrapper{
        background-color: #f0f0f5;
        padding: 15px 20px 18px;
        border-radius: 6px;
        background-color: rgba(84, 168, 251, 0.1);
        .app-detail{
          display: flex;
          justify-content: center;
          align-items: center;
          margin-top: 12px;
          h6{
            font-weight: 600;
          }
        }
        .btn{
          background-color: variables.$primary-color;
          color: variables.$white;
          font-weight: 600;
          border: none;
          border-radius: 4px;
          padding: 8px;
        }
        &:hover{
          img{
            transform: scale(1.02);
            transition: all 0.5s ease-in-out;
          }
        }
      }
      .app-image{
        img{
          border-radius: 6px;
          box-shadow: 0 0 20px 1px rgba(0,0,0,.08);
          width: 100%;
          margin-top: 15px;
          transition: all 0.5s ease-in-out;
        }
      }
    }
  }

  .features-section{
    background-color: rgba(129, 131, 133, 0.06);
    .feature-box{
      position: relative;
      height: 100%;
      display: flex;
      -webkit-box-align: center;
      -ms-flex-align: center;
      align-items: center;
      background: #FCFCFD;
      -webkit-box-shadow: 0px 5px 20px rgba(46, 35, 94, 0.12);
      box-shadow: 0px 5px 20px rgba(46, 35, 94, 0.12);
      border-radius: 10px;
      padding: 18px 16px;
      gap: 16px;
      margin-left: 30px;
      -webkit-transition: all 0.5s;
      transition: all 0.5s;
      .feature-icon{
        position: relative;
        min-width: 55px;
        height: 55px;
        background: variables.$white;
        border-radius: 100%;
        display: -webkit-box;
        display: -ms-flexbox;
        display: flex;
        align-items: center;
        justify-content: center;
        margin-left: -32px;
        margin-top: -100px;
        @media (max-width: 575px) {
          min-width: 52px;
          height: 52px;
          margin: 0;
        }
        &::before{
          position: absolute;
          content: "";
          width: 100%;
          height: 100%;
          left: 0;
          top: 0;
          -webkit-box-shadow: 3px 4px 5px rgba(46, 35, 94, 0.11), inset 3px 0px 1px rgba(204, 204, 215, 0.5);
          box-shadow: 3px 4px 5px rgba(46, 35, 94, 0.11), inset 3px 0px 1px rgba(204, 204, 215, 0.5);
          border-radius: 100%;
        }
        svg{
          width: 30px;
          height: 30px;
          @media (max-width: 575px) {
            width: 25px;
            height: 25px;
          }
        }
      }
      &:hover{
        transform: scale(1.02);
        transition: all 0.5s;
        background-color: rgb(84 168 251 / 6%);
        .feature-details{
          h5{
            color: variables.$primary-color;
            transition: all 0.5s;
          }
          p{
            opacity: 0.7;
            margin-bottom: 0;
          }
        }
      }
      @media (max-width: 575px) {
        margin-left: 0;
        -webkit-box-orient: vertical;
        -webkit-box-direction: normal;
        flex-direction: column;
      }
    }
    .feature-details{
      position: relative;
      text-align: left;
      @media (max-width: 575px) {
        text-align: center;
      }
    }
  }
  .license-support{
    .image-wrapper{
      display: flex;
      align-items: center;
      justify-content: center;
      img{
        animation: float 4s ease-in-out infinite;
      }
    }
    .support-wrapper{
      display: flex;
      justify-content: center;
      align-items: flex-start;
      flex-direction: column;
      padding: 12px;
      text-align: left;
      .title{
        margin-bottom: 10px;
      }
      h2{
        color: variables.$primary-color;
        font-size: 30px;
        font-weight: bold;
      }
      h3{
        font-size: 18px;
        padding-top: 6px;
        font-weight: 700;
        padding-bottom: 10px;
        text-transform: capitalize;
      }
      .description{
        margin-bottom: 40px;
        color: variables.$theme-body-sub-title-color;
        font-size: 16px;
        letter-spacing: 0.7px;
        @media (max-width: 1240px) and (min-width: 320px) {
          margin-bottom: 16px;
        }
        @media (max-width: 991px) and (min-width: 320px) {
          text-overflow: ellipsis;
          height: 47px;
          -webkit-line-clamp: 2;
          -webkit-box-orient: vertical;
          overflow: hidden;
          display: -webkit-box;
        }
      }
      .link-text{
        color: variables.$white;
        background-color: variables.$primary-color;
      }
    }
  }

  // footer section
  .landing-footer {
    background-color: #172834;
    overflow: hidden;
    .footer-contain {
      text-align: center;
      img {
        margin-bottom: 5px;
      }
      h2 {
        font-size: calc(18px + (35 - 18) * ((100vw - 320px) / (1920 - 320)));
        font-weight: 700;
        color: variables.$light-semi-gray;
        margin-bottom: 10px;
        line-height: 1.4;
      }
      .star-rate {
        margin-bottom: 40px;
        li {
          display: inline-block;
          i {
            font-size: calc(16px + (30 - 16) * ((100vw - 320px) / (1920 - 320)));
          }
        }
      }
      .btn-footer {
        a {
          &:nth-child(n + 2) {
            margin-left: 10px;
          }
          @media (max-width: 405px) {
            &:last-child{
              margin-top: 10px;
            }
          }
        }
      }
    }
    .custom-container{
      @media (max-width: 575px) {
        padding-inline: 15px;
      }
    }
  }
}

@media (max-width:1199px) {
// header //
  .landing-page{
    .landing-header{
      padding: 15px 40px;
      ul{
        &.landing-menu{
          li{
            &.nav-item{
              a{
                &.nav-link{
                  padding: 10px 8px;
                }
              }
            }
          }
        }
      }
      .buy-lock{
        .btn-heading{
          padding: 10px 20px;
        }
      }
    }
  }
}
@media (max-width: 991px) {
  .landing-page{
    .landing-header{
      ul{
        &.landing-menu{
          position: fixed;
          top: 0;
          right: -320px;
          display: block;
          width: 300px;
          height: 100vh;
          z-index: 1;
          background-color: variables.$white;
          transition: all 0.5s ease;
          li{
            &.nav-item{
              a{
                &.nav-link{
                  color: variables.$theme-body-font-color;
                  padding: 10px 20px;
                }
              }
              &.menu-back{
                display: block;
              }
            }
          }
          &.open{
            right: 0;
          }
        }
      }
      .buy-block{
        .toggle-menu{
          display: block;
        }
      }
    }
  }
}
@media (max-width:767px) {
  .landing-page{
    .landing-header{
      position: relative;
      background-color: variables.$theme-body-font-color;
    }
  }
}
@media (max-width: 480px) {
  .landing-page{
    .landing-header{
      .buy-block{
        .toggle-menu{
          margin-left: 10px;
        }
      }
    }
  }
}
@media (max-width: 360px) {
  .landing-page{
    .landing-header{
      padding: 6px 8px;
    }
  }
}

@keyframes float {
  0%{
    transform: translateY(0);
  }
  50%{
    transform: translateY(-10px);
  }
  100%{
    transform: translateY(0);
  }
}
@keyframes upDown {
  0%{
    transform: translateY(0px);
  }
